CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "EmploymentType" AS ENUM ('PERMANENT','CONTRACT','PART_TIME','TEMPORARY','DAILY_WAGE','OTHER');
CREATE TYPE "StaffStatus" AS ENUM ('ACTIVE','PROBATION','ON_LEAVE','SUSPENDED','RESIGNED','TERMINATED','RETIRED','ARCHIVED');
CREATE TYPE "SalaryFrequency" AS ENUM ('MONTHLY','WEEKLY','DAILY');
CREATE TYPE "SalaryRecordStatus" AS ENUM ('DRAFT','PENDING','PARTIALLY_PAID','PAID','ON_HOLD','CANCELLED','REVERSED');
CREATE TYPE "SalaryPaymentMethod" AS ENUM ('CASH','BANK_TRANSFER','CHEQUE','DIGITAL_TRANSFER','OTHER');
CREATE TYPE "SalaryAdjustmentType" AS ENUM ('ALLOWANCE','DEDUCTION','DEBIT_CORRECTION','CREDIT_CORRECTION');
CREATE TYPE "SalaryPaymentStatus" AS ENUM ('CONFIRMED','REVERSED','PARTIALLY_REVERSED');
CREATE TYPE "SalarySlipStatus" AS ENUM ('ACTIVE','REVERSED');
CREATE TYPE "WorkerRelationship" AS ENUM ('INTERNAL','EXTERNAL_CONTRACTOR');
CREATE TYPE "WorkerStatus" AS ENUM ('AVAILABLE','BUSY','OFF_DUTY','ON_LEAVE','SUSPENDED','INACTIVE','ARCHIVED');
CREATE TYPE "WorkforceDocumentStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "AvailabilityOverrideType" AS ENUM ('AVAILABLE','UNAVAILABLE','LEAVE');
CREATE TYPE "ScheduleReservationStatus" AS ENUM ('RESERVED','CANCELLED','COMPLETED');

CREATE TABLE "department" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"name" VARCHAR(120) NOT NULL,"normalized_name" VARCHAR(120) NOT NULL,"description" VARCHAR(500),"display_order" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_department_society_name" UNIQUE("society_id","normalized_name"));
CREATE INDEX "department_society_active_order_idx" ON "department"("society_id","active","display_order");
CREATE TABLE "job_title" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"department_id" UUID NOT NULL REFERENCES "department"("id") ON DELETE RESTRICT,"name" VARCHAR(120) NOT NULL,"normalized_name" VARCHAR(120) NOT NULL,"description" VARCHAR(500),"display_order" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_job_title_department_name" UNIQUE("department_id","normalized_name"));
CREATE INDEX "job_title_society_active_order_idx" ON "job_title"("society_id","active","display_order");

CREATE TABLE "staff_member" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"user_id" UUID UNIQUE REFERENCES "user_account"("id") ON DELETE RESTRICT,"staff_number" VARCHAR(80) NOT NULL,"full_name" VARCHAR(160) NOT NULL,"normalized_full_name" VARCHAR(160) NOT NULL,"guardian_name" VARCHAR(160),"identity_ciphertext" TEXT,"identity_search_hash" CHAR(64),"identity_last_four" VARCHAR(4),"date_of_birth" DATE,"gender" "Gender" NOT NULL DEFAULT 'UNDISCLOSED',"email" VARCHAR(254),"primary_phone" VARCHAR(30) NOT NULL,"alternate_phone" VARCHAR(30),"address" VARCHAR(500),"emergency_contact_name" VARCHAR(160),"emergency_contact_phone" VARCHAR(30),"status" "StaffStatus" NOT NULL DEFAULT 'ACTIVE',"archived_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_staff_society_number" UNIQUE("society_id","staff_number"));
CREATE INDEX "staff_society_status_number_idx" ON "staff_member"("society_id","status","staff_number");
CREATE INDEX "staff_society_name_idx" ON "staff_member"("society_id","normalized_full_name");
CREATE INDEX "staff_society_phone_idx" ON "staff_member"("society_id","primary_phone");
CREATE INDEX "staff_society_identity_idx" ON "staff_member"("society_id","identity_search_hash");
CREATE TABLE "employment_record" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"staff_id" UUID NOT NULL REFERENCES "staff_member"("id") ON DELETE RESTRICT,"department_id" UUID NOT NULL REFERENCES "department"("id") ON DELETE RESTRICT,"job_title_id" UUID NOT NULL REFERENCES "job_title"("id") ON DELETE RESTRICT,"supervisor_staff_id" UUID REFERENCES "staff_member"("id") ON DELETE RESTRICT,"employment_type" "EmploymentType" NOT NULL,"joining_date" DATE NOT NULL,"probation_end_date" DATE,"effective_from" DATE NOT NULL,"effective_to" DATE,"work_shift" VARCHAR(100),"payment_method" "SalaryPaymentMethod","bank_details_ciphertext" TEXT,"notes" VARCHAR(1000),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CHECK("effective_to" IS NULL OR "effective_to">="effective_from"),CHECK("probation_end_date" IS NULL OR "probation_end_date">="joining_date"));
CREATE INDEX "employment_staff_dates_idx" ON "employment_record"("staff_id","effective_from","effective_to");
CREATE INDEX "employment_department_title_idx" ON "employment_record"("department_id","job_title_id");
CREATE TABLE "staff_status_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"staff_id" UUID NOT NULL REFERENCES "staff_member"("id") ON DELETE RESTRICT,"from_status" "StaffStatus","to_status" "StaffStatus" NOT NULL,"reason" VARCHAR(500) NOT NULL,"effective_at" TIMESTAMPTZ(6) NOT NULL,"acted_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "staff_status_history_staff_date_idx" ON "staff_status_history"("staff_id","effective_at");
CREATE TABLE "staff_document" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"staff_id" UUID NOT NULL REFERENCES "staff_member"("id") ON DELETE RESTRICT,"category" VARCHAR(80) NOT NULL,"object_key" VARCHAR(500) NOT NULL UNIQUE,"original_file_name" VARCHAR(255) NOT NULL,"media_type" VARCHAR(120) NOT NULL,"size_bytes" BIGINT NOT NULL CHECK("size_bytes">0),"checksum_sha256" CHAR(64) NOT NULL,"status" "WorkforceDocumentStatus" NOT NULL DEFAULT 'ACTIVE',"uploaded_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"archived_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "staff_document_staff_category_status_idx" ON "staff_document"("staff_id","category","status");

CREATE TABLE "salary_structure" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"staff_id" UUID NOT NULL REFERENCES "staff_member"("id") ON DELETE RESTRICT,"basic_salary" DECIMAL(18,2) NOT NULL CHECK("basic_salary">=0),"fixed_allowances" DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK("fixed_allowances">=0),"fixed_deductions" DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK("fixed_deductions">=0),"frequency" "SalaryFrequency" NOT NULL DEFAULT 'MONTHLY',"currency" CHAR(3) NOT NULL,"effective_from" DATE NOT NULL,"effective_to" DATE,"notes" VARCHAR(500),"created_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CHECK("effective_to" IS NULL OR "effective_to">="effective_from"));
CREATE INDEX "salary_structure_staff_dates_idx" ON "salary_structure"("staff_id","effective_from","effective_to");
ALTER TABLE "salary_structure" ADD CONSTRAINT "salary_structure_no_overlap" EXCLUDE USING gist ("staff_id" WITH =,daterange("effective_from",COALESCE("effective_to",'infinity'::date),'[]') WITH &&);
CREATE TABLE "salary_period" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"year" INTEGER NOT NULL,"month" INTEGER NOT NULL CHECK("month" BETWEEN 1 AND 12),"starts_at" DATE NOT NULL,"ends_at" DATE NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "uk_salary_period_society_month" UNIQUE("society_id","year","month"));
CREATE TABLE "salary_record" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"staff_id" UUID NOT NULL REFERENCES "staff_member"("id") ON DELETE RESTRICT,"salary_period_id" UUID NOT NULL REFERENCES "salary_period"("id") ON DELETE RESTRICT,"salary_structure_id" UUID NOT NULL REFERENCES "salary_structure"("id") ON DELETE RESTRICT,"basic_salary" DECIMAL(18,2) NOT NULL,"allowances" DECIMAL(18,2) NOT NULL DEFAULT 0,"deductions" DECIMAL(18,2) NOT NULL DEFAULT 0,"adjustment_total" DECIMAL(18,2) NOT NULL DEFAULT 0,"net_payable" DECIMAL(18,2) NOT NULL,"amount_paid" DECIMAL(18,2) NOT NULL DEFAULT 0,"currency" CHAR(3) NOT NULL,"status" "SalaryRecordStatus" NOT NULL DEFAULT 'PENDING',"salary_snapshot" JSONB NOT NULL,"generated_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"generated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"paid_at" TIMESTAMPTZ(6),"notes" VARCHAR(500),"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_salary_record_staff_period" UNIQUE("staff_id","salary_period_id"),CHECK("net_payable">=0 AND "amount_paid">=0 AND "amount_paid"<="net_payable"));
CREATE INDEX "salary_record_period_status_idx" ON "salary_record"("salary_period_id","status");
CREATE TABLE "salary_payment" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"salary_record_id" UUID NOT NULL REFERENCES "salary_record"("id") ON DELETE RESTRICT,"amount" DECIMAL(18,2) NOT NULL CHECK("amount">0),"reversed_amount" DECIMAL(18,2) NOT NULL DEFAULT 0,"currency" CHAR(3) NOT NULL,"method" "SalaryPaymentMethod" NOT NULL,"status" "SalaryPaymentStatus" NOT NULL DEFAULT 'CONFIRMED',"payment_date" TIMESTAMPTZ(6) NOT NULL,"transaction_reference" VARCHAR(180) UNIQUE,"notes" VARCHAR(500),"proof_object_key" VARCHAR(500),"recorded_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"idempotency_key" VARCHAR(180) NOT NULL UNIQUE,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("reversed_amount">=0 AND "reversed_amount"<="amount"));
CREATE INDEX "salary_payment_record_date_idx" ON "salary_payment"("salary_record_id","payment_date");
CREATE TABLE "salary_adjustment" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"salary_record_id" UUID NOT NULL REFERENCES "salary_record"("id") ON DELETE RESTRICT,"type" "SalaryAdjustmentType" NOT NULL,"amount" DECIMAL(18,2) NOT NULL CHECK("amount">0),"reason" VARCHAR(500) NOT NULL,"acted_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"idempotency_key" VARCHAR(180) NOT NULL UNIQUE,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "salary_adjustment_record_date_idx" ON "salary_adjustment"("salary_record_id","created_at");
CREATE TABLE "salary_slip" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"salary_record_id" UUID NOT NULL REFERENCES "salary_record"("id") ON DELETE RESTRICT,"slip_number" VARCHAR(100) NOT NULL UNIQUE,"verification_hash" CHAR(64) NOT NULL UNIQUE,"pdf_object_key" VARCHAR(500) NOT NULL,"status" "SalarySlipStatus" NOT NULL DEFAULT 'ACTIVE',"issued_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"issued_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reversed_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "salary_slip_record_status_idx" ON "salary_slip"("salary_record_id","status");
CREATE TABLE "staff_id_sequence" ("society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"sequence_year" INTEGER NOT NULL,"next_value" BIGINT NOT NULL DEFAULT 1,"updated_at" TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY("society_id","sequence_year"));
CREATE TABLE "salary_slip_sequence" ("society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"sequence_year" INTEGER NOT NULL,"next_value" BIGINT NOT NULL DEFAULT 1,"updated_at" TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY("society_id","sequence_year"));

CREATE TABLE "contractor_company" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"name" VARCHAR(160) NOT NULL,"normalized_name" VARCHAR(160) NOT NULL,"contact_name" VARCHAR(160),"phone" VARCHAR(30),"email" VARCHAR(254),"address" VARCHAR(500),"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_contractor_society_name" UNIQUE("society_id","normalized_name"));
CREATE TABLE "worker_category" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"code" VARCHAR(30) NOT NULL,"name" VARCHAR(120) NOT NULL,"description" VARCHAR(500),"default_duration_minutes" INTEGER,"default_rate" DECIMAL(18,2),"currency" CHAR(3),"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_worker_category_society_code" UNIQUE("society_id","code"),CONSTRAINT "uk_worker_category_society_name" UNIQUE("society_id","name"),CHECK(("default_duration_minutes" IS NULL OR "default_duration_minutes">0) AND ("default_rate" IS NULL OR "default_rate">=0)));
CREATE INDEX "worker_category_society_active_idx" ON "worker_category"("society_id","active");
CREATE TABLE "worker_skill" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"name" VARCHAR(120) NOT NULL,"normalized_name" VARCHAR(120) NOT NULL,"description" VARCHAR(500),"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "uk_worker_skill_society_name" UNIQUE("society_id","normalized_name"));
CREATE TABLE "service_worker" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"user_id" UUID UNIQUE REFERENCES "user_account"("id") ON DELETE RESTRICT,"worker_number" VARCHAR(100) NOT NULL,"primary_category_id" UUID NOT NULL REFERENCES "worker_category"("id") ON DELETE RESTRICT,"contractor_company_id" UUID REFERENCES "contractor_company"("id") ON DELETE RESTRICT,"full_name" VARCHAR(160) NOT NULL,"normalized_full_name" VARCHAR(160) NOT NULL,"identity_ciphertext" TEXT,"identity_search_hash" CHAR(64),"identity_last_four" VARCHAR(4),"date_of_birth" DATE,"primary_phone" VARCHAR(30) NOT NULL,"alternate_phone" VARCHAR(30),"email" VARCHAR(254),"address" VARCHAR(500),"emergency_contact" VARCHAR(200),"relationship" "WorkerRelationship" NOT NULL,"experience_years" INTEGER NOT NULL DEFAULT 0 CHECK("experience_years">=0),"service_area" VARCHAR(160) NOT NULL,"rate_notes" VARCHAR(500),"registration_date" DATE NOT NULL,"status" "WorkerStatus" NOT NULL DEFAULT 'AVAILABLE',"administrative_notes" VARCHAR(1000),"archived_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_worker_society_number" UNIQUE("society_id","worker_number"));
CREATE INDEX "worker_society_status_category_idx" ON "service_worker"("society_id","status","primary_category_id");
CREATE INDEX "worker_society_name_idx" ON "service_worker"("society_id","normalized_full_name");
CREATE INDEX "worker_society_area_idx" ON "service_worker"("society_id","service_area");
CREATE TABLE "worker_skill_assignment" ("worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"skill_id" UUID NOT NULL REFERENCES "worker_skill"("id") ON DELETE RESTRICT,"proficiency" VARCHAR(80),"assigned_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("worker_id","skill_id"));
CREATE INDEX "worker_skill_assignment_skill_idx" ON "worker_skill_assignment"("skill_id");
CREATE TABLE "worker_availability" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"day_of_week" INTEGER NOT NULL,"start_minute" INTEGER NOT NULL,"end_minute" INTEGER NOT NULL,"service_area" VARCHAR(160),"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "uk_worker_availability_window" UNIQUE("worker_id","day_of_week","start_minute","end_minute"),CHECK("day_of_week" BETWEEN 0 AND 6 AND "start_minute">=0 AND "end_minute"<=1440 AND "start_minute"<"end_minute"));
CREATE INDEX "worker_availability_worker_day_idx" ON "worker_availability"("worker_id","day_of_week","active");
CREATE TABLE "worker_availability_override" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"type" "AvailabilityOverrideType" NOT NULL,"starts_at" TIMESTAMPTZ(6) NOT NULL,"ends_at" TIMESTAMPTZ(6) NOT NULL,"reason" VARCHAR(500) NOT NULL,"created_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("ends_at">"starts_at"));
CREATE INDEX "worker_override_worker_dates_idx" ON "worker_availability_override"("worker_id","starts_at","ends_at");
CREATE TABLE "worker_schedule_reservation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"starts_at" TIMESTAMPTZ(6) NOT NULL,"ends_at" TIMESTAMPTZ(6) NOT NULL,"service_area" VARCHAR(160),"purpose" VARCHAR(300) NOT NULL,"status" "ScheduleReservationStatus" NOT NULL DEFAULT 'RESERVED',"created_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"cancelled_at" TIMESTAMPTZ(6),"cancellation_reason" VARCHAR(500),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"version" INTEGER NOT NULL DEFAULT 0,CHECK("ends_at">"starts_at"));
CREATE INDEX "worker_reservation_worker_status_dates_idx" ON "worker_schedule_reservation"("worker_id","status","starts_at","ends_at");
ALTER TABLE "worker_schedule_reservation" ADD CONSTRAINT "worker_reservation_no_overlap" EXCLUDE USING gist ("worker_id" WITH =,tstzrange("starts_at","ends_at",'[)') WITH &&) WHERE ("status"='RESERVED');
CREATE TABLE "worker_rate" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"amount" DECIMAL(18,2) NOT NULL CHECK("amount">=0),"currency" CHAR(3) NOT NULL,"unit" VARCHAR(40) NOT NULL,"effective_from" DATE NOT NULL,"effective_to" DATE,"notes" VARCHAR(500),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("effective_to" IS NULL OR "effective_to">="effective_from"));
CREATE INDEX "worker_rate_worker_dates_idx" ON "worker_rate"("worker_id","effective_from","effective_to");
CREATE TABLE "worker_document" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"category" VARCHAR(80) NOT NULL,"object_key" VARCHAR(500) NOT NULL UNIQUE,"original_file_name" VARCHAR(255) NOT NULL,"media_type" VARCHAR(120) NOT NULL,"size_bytes" BIGINT NOT NULL CHECK("size_bytes">0),"checksum_sha256" CHAR(64) NOT NULL,"status" "WorkforceDocumentStatus" NOT NULL DEFAULT 'ACTIVE',"uploaded_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"archived_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "worker_document_worker_category_status_idx" ON "worker_document"("worker_id","category","status");
CREATE TABLE "worker_performance_note" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"reliability" INTEGER,"work_quality" INTEGER,"note" VARCHAR(1000) NOT NULL,"review_date" DATE NOT NULL,"reviewed_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(("reliability" IS NULL OR "reliability" BETWEEN 1 AND 5) AND ("work_quality" IS NULL OR "work_quality" BETWEEN 1 AND 5)));
CREATE INDEX "worker_performance_worker_date_idx" ON "worker_performance_note"("worker_id","review_date");
CREATE TABLE "worker_status_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"worker_id" UUID NOT NULL REFERENCES "service_worker"("id") ON DELETE RESTRICT,"from_status" "WorkerStatus","to_status" "WorkerStatus" NOT NULL,"reason" VARCHAR(500) NOT NULL,"effective_at" TIMESTAMPTZ(6) NOT NULL,"acted_by_user_id" UUID NOT NULL REFERENCES "user_account"("id") ON DELETE RESTRICT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "worker_status_history_worker_date_idx" ON "worker_status_history"("worker_id","effective_at");
CREATE TABLE "worker_id_sequence" ("society_id" UUID NOT NULL REFERENCES "society"("id") ON DELETE RESTRICT,"category_code" VARCHAR(30) NOT NULL,"sequence_year" INTEGER NOT NULL,"next_value" BIGINT NOT NULL DEFAULT 1,"updated_at" TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY("society_id","category_code","sequence_year"));
